  reg_val = hal_readl(base_addr + LEDC_CTRL_REG);
  reg_val &= ~(0x1FFF << 16);
  reg_val |= length << 16;
  hal_writel(reg_val, base_addr + LEDC_CTRL_REG);

  reg_val = hal_readl(base_addr + LED_RST_TIMING_CTRL_REG);
  reg_val &= ~0x3FF;
  reg_val |= length - 1;
  hal_writel(reg_val, base_addr + LED_RST_TIMING_CTRL_REG);
}

