121	void led_strip_set_pct(int pct)
122	{
123	  uint32_t active;
124	  uint32_t reg;
125	
126	  if (pct < 0)
127	    {
128	      pct = 0;
129	    }
130	  else if (pct > 100)
131	    {
132	      pct = 100;
133	    }
134	
135	  active = (uint32_t)STRIP_PERIOD_CYCLES * (uint32_t)pct / 100u;
136	
137	  reg  = PWM_REG(LED_PWM_PPR(STRIP_PWM_CH));
138	  reg &= 0xffff0000u;                       /* 清掉 [15:0] active cycles */
139	  reg |= active & 0xffffu;
140	  PWM_REG(LED_PWM_PPR(STRIP_PWM_CH)) = reg;
141	}
