143	static void strip_pwm_init(void)
144	{
145	  uint32_t reg;
146	
147	  /* 只借它打开 PWM 总线时钟。显示背光在 LCD 初始化时已经调用过一次，
148	   * 这里是引用计数 +1，不会重置控制器。 */
149	
150	  hal_pwm_init();
151	
152	  /* 通道 2：24 MHz 源、不分频。 */
153	
154	  reg  = PWM_REG(LED_PWM_PCCR23);
155	  reg &= ~((0x3u << 7) | 0xfu);             /* clk_src = OSC24M, div_m = 0 */
156	  PWM_REG(LED_PWM_PCCR23) = reg;
157	
158	  /* 打开通道 2 的时钟门控。 */
159	
160	  PWM_REG(LED_PWM_PCGR) |= (1u << STRIP_PWM_CH);
161	
162	  /* 预分频 0，正常极性（占空比期间输出高）。 */
163	
164	  PWM_REG(LED_PWM_PCR(STRIP_PWM_CH)) = PWM_PCR_ACTIVE_HIGH;
165	
166	  /* 周期和初始占空比（0，灯带先灭）。 */
167	
168	  PWM_REG(LED_PWM_PPR(STRIP_PWM_CH)) =
169	      ((STRIP_PERIOD_CYCLES - 1) << 16);
170	
171	  /* 使能通道 2。 */
172	
173	  PWM_REG(LED_PWM_PER) |= (1u << STRIP_PWM_CH);
174	}
